package com.example.starter.ledger.domain;

/**
 * 电池资产状态。
 */
public enum BatteryStatus {
    /** 已建档，尚未入站。 */
    REGISTERED,
    /** 已入站（在站点、待检测）。 */
    AT_STATION,
    /** 检测合格，已上架可换。 */
    AVAILABLE,
    /** 检测不合格，充电/待修。 */
    CHARGING,
    /** 已换出，车辆侧在用。 */
    IN_USE,
    /** 站间调拨在途。 */
    IN_TRANSIT,
    /** 调拨异常（在途超过 24 小时），待人工核销。 */
    TRANSFER_EXCEPTION,
    /** 已人工核销，终态。 */
    WRITTEN_OFF
}

package com.example.starter.starter.ledger.domain;

/**
 * 电池资产流转事件类型，按事件链顺序追加。
 */
public enum EventType {
    /** 建档（事件链起点）。 */
    REGISTER,
    /** 回站入站。 */
    INBOUND,
    /** 检测（结论不可修改）。 */
    INSPECTION,
    /** 检测合格后上架可换。 */
    LISTING,
    /** 换出并绑定车辆。 */
    SWAP_OUT,
    /** 站间调拨调出，进入在途。 */
    TRANSFER_DISPATCH,
    /** 调入方到站签收。 */
    TRANSFER_RECEIVE,
    /** 在途超时，调拨异常。 */
    TRANSFER_EXCEPTION,
    /** 人工核销。 */
    TRANSFER_WRITEOFF
}

