package com.example.starter.ledger.po;

import java.time.Instant;

/**
 * 电池资产主表 PO。时间字段统一为 UTC。
 */
public class BatteryPO {

    /** 主键。 */
    private Long id;
    /** 电池唯一编码。 */
    private String code;
    /** 资产状态，取值见 {@link com.example.starter.ledger.domain.BatteryStatus}。 */
    private String status;
    /** 当前所在站点编码；空值表示不在站（在用/在途/核销）。 */
    private String currentStation;
    /** 绑定车辆编码；空值表示未绑定车辆。 */
    private String boundVehicle;
    /** 事件链最新事件哈希；空值表示尚无事件。 */
    private String headEventHash;
    /** 乐观锁版本号。 */
    private long version;
    /** 建档时间（UTC）。 */
    private Instant createdAt;
    /** 最近更新时间（UTC）。 */
    private Instant updatedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getCurrentStation() {
        return currentStation;
    }

    public void setCurrentStation(String currentStation) {
        this.currentStation = currentStation;
    }

    public String getBoundVehicle() {
        return boundVehicle;
    }

    public void setBoundVehicle(String boundVehicle) {
        this.boundVehicle = boundVehicle;
    }

    public String getHeadEventHash() {
        return headEventHash;
    }

    public void setHeadEventHash(String headEventHash) {
        this.headEventHash = headEventHash;
    }

    public long getVersion() {
        return version;
    }

    public void setVersion(long version) {
        this.version = version;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.ledger.po;

import java.time.Instant;

/**
 * 电池流转事件 PO，事件以哈希链串联，可逐条验真。
 */
public class LedgerEventPO {

    /** 主键。 */
    private Long id;
    /** 电池唯一编码。 */
    private String batteryCode;
    /** 链内序号，从 1 递增。 */
    private long seq;
    /** 事件类型，取值见 {@link com.example.starter.ledger.domain.EventType}。 */
    private String eventType;
    /** 上一事件哈希；首事件为 64 个 0。 */
    private String prevHash;
    /** 本事件哈希（SHA-256）。 */
    private String eventHash;
    /** 事件业务字段规范化 JSON。 */
    private String payload;
    /** 产生该事件的幂等请求标识；建档事件为空。 */
    private String requestId;
    /** 事件发生时间（UTC）。 */
    private Instant occurredAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getBatteryCode() {
        return batteryCode;
    }

    public void setBatteryCode(String batteryCode) {
        this.batteryCode = batteryCode;
    }

    public long getSeq() {
        return seq;
    }

    public void setSeq(long seq) {
        this.seq = seq;
    }

    public String getEventType() {
        return eventType;
    }

    public void setEventType(String eventType) {
        this.eventType = eventType;
    }

    public String getPrevHash() {
        return prevHash;
    }

    public void setPrevHash(String prevHash) {
        this.prevHash = prevHash;
    }

    public String getEventHash() {
        return eventHash;
    }

    public void setEventHash(String eventHash) {
        this.eventHash = eventHash;
    }

    public String getPayload() {
        return payload;
    }

    public void setPayload(String payload) {
        this.payload = payload;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }

    public void setOccurredAt(Instant occurredAt) {
        this.occurredAt = occurredAt;
    }
}

package com.example.starter.ledger.po;

import java.time.Instant;

/**
 * 站间调拨单 PO。调出方发起、调入方签收，在途超时转异常，异常人工核销且仅一次。
 */
public class TransferOrderPO {

    /** 主键。 */
    private Long id;
    /** 调拨单号。 */
    private String orderNo;
    /** 调拨电池编码。 */
    private String batteryCode;
    /** 调出站点编码（发起方）。 */
    private String fromStation;
    /** 调入站点编码（签收方）。 */
    private String toStation;
    /** 调拨状态，取值见 {@link com.example.starter.ledger.domain.TransferStatus}。 */
    private String status;
    /** 调出时间（UTC），在途计时起点。 */
    private Instant dispatchedAt;
    /** 签收时间（UTC）；空值表示尚未签收。 */
    private Instant receivedAt;
    /** 超时转异常时间（UTC）；空值表示正常在途或已签收。 */
    private Instant exceptionAt;
    /** 人工核销时间（UTC）；空值表示未核销。 */
    private Instant writtenOffAt;
    /** 核销原因；空值表示未核销。 */
    private String writeoffReason;
    /** 乐观锁版本号。 */
    private long version;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getOrderNo() {
        return orderNo;
    }

    public void setOrderNo(String orderNo) {
        this.orderNo = orderNo;
    }

    public String getBatteryCode() {
        return batteryCode;
    }

    public void setBatteryCode(String batteryCode) {
        this.batteryCode = batteryCode;
    }

    public String getFromStation() {
        return fromStation;
    }

    public void setFromStation(String fromStation) {
        this.fromStation = fromStation;
    }

    public String getToStation() {
        return toStation;
