                order.getExceptionAt() == null ? null : Timestamp.from(order.getExceptionAt()),
                order.getWrittenOffAt() == null ? null : Timestamp.from(order.getWrittenOffAt()),
                order.getWriteoffReason(), order.getVersion());
    }

