    public TransferOrderPO lockByOrderNo(String orderNo) {
        try {
            return jdbcTemplate.queryForObject(
                    "SELECT " + COLUMNS + " FROM transfer_order WHERE order_no = ? FOR UPDATE", MAPPER, orderNo);
        } catch (EmptyResultDataAccessException e) {
