package com.example.starter.ledger.service;

import com.example.starter.ledger.po.ChainAlertPO;
import com.example.starter.ledger.repo.ChainAlertRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * 链不一致告警服务：即使业务事务最终回滚，告警也必须独立落库。
 */
@Service
public class AlertService {

    private final ChainAlertRepository chainAlertRepository;

    public AlertService(ChainAlertRepository chainAlertRepository) {
        this.chainAlertRepository = chainAlertRepository;
    }

    /** 在独立事务中落库告警，不受外层业务回滚影响。 */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void recordInNewTransaction(ChainAlertPO alert) {
        chainAlertRepository.insert(alert);
    }
}

package com.example.starter.ledger.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

/**
 * 调拨超时扫描器：固定延迟检查在途超过 24 小时（UTC）的调拨单并转异常。
 * 测试中可直接调用 {@link LedgerService#markTimedOutTransfers()} 精确控制时钟。
 */
@Component
public class TransferTimeoutScheduler {

    private static final Logger log = LoggerFactory.getLogger(TransferTimeoutScheduler.class);

    private final LedgerService ledgerService;

    public TransferTimeoutScheduler(LedgerService ledgerService) {
        this.ledgerService = ledgerService;
    }

    /** 每 15 分钟扫描一次；单实例内存服务无需分布式锁。 */
    @Scheduled(fixedDelayString = "${battery.ledger.timeout-scan-delay-ms:900000}")
    public void scan() {
        int marked = ledgerService.markTimedOutTransfers();
        if (marked > 0) {
            log.warn("调拨在途超时，自动转异常 {} 单", marked);
        }
    }
}

